-- Demo PERF-07: ID produk dari sequence dengan kenaikan 50 (pooled
-- optimizer Hibernate), agar INSERT massal dapat di-batch. Dengan
-- IDENTITY, Hibernate harus menjalankan setiap INSERT satu per satu
-- untuk membaca ID yang dibuat database.
--
-- Kolom id tetap GENERATED BY DEFAULT AS IDENTITY, jadi INSERT manual
-- (misalnya seed) masih berjalan; ID dari aplikasi kini selalu eksplisit.
--
-- Pooled optimizer memperlakukan nilai sequence sebagai batas ATAS blok
-- 50 ID (nilai v berarti ID v-49 sampai v). Karena itu nilai awalnya
-- max(id) + 50, bukan max(id) + 1 (yang menghasilkan ID negatif atau
-- bentrok dengan ID lama).
CREATE SEQUENCE products_seq INCREMENT BY 50;
SELECT setval('products_seq',
              (SELECT coalesce(max(id), 0) + 50 FROM products), false);
